target.css:
:root {
  --ink: #20323a;
  --paper: #fffdf7;
  --pine: #285660;
  --mint: #dcefe5;
  --coral: #e96f58;
  --line: #b9d1c8;
  --sun: #f3c75d;
}

* {
  box-sizing: border-box;
}

.belay-card {
  width: 480px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 15px 18px 13px;
  border-bottom: 1px solid var(--line);
}

.eyebrow {
  margin: 0;
  color: var(--pine);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.09em;
  line-height: 1.2;
}

.eyebrow span {
  display: inline-block;
  margin-left: 8px;
  padding: 3px 6px;
  color: var(--pine);
  background: var(--mint);
  border-radius: 999px;
  font-size: 9px;
  letter-spacing: 0.06em;
}

h1 {
  margin: 7px 0 0;
  font-size: 22px;
  line-height: 1.05;
  letter-spacing: -0.04em;
}

.slot-body {
  display: flex;
  gap: 15px;
  padding: 14px 18px;
}

.route-badge {
  display: flex;
  flex: 0 0 76px;
  align-items: center;
  justify-content: center;
  min-height: 82px;
  margin: 0;
  color: var(--paper);
  background: var(--coral);
  border: 4px solid var(--sun);
  border-radius: 14px 14px 28px 14px;
  flex-direction: column;
}

.route-badge strong {
  font-size: 24px;
  line-height: 0.95;
  letter-spacing: -0.06em;
}

.route-badge figcaption {
  margin-top: 5px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.booking-details {
  flex: 1;
  min-width: 0;
}

.climber-name {
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 1px 0 10px;
  font-size: 15px;
  font-weight: 800;
  line-height: 1;
}

.climber-name span {
  padding: 3px 6px;
  color: var(--coral);
  background: var(--paper);
  border: 1px solid var(--coral);
  border-radius: 5px;
  font-size: 9px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.detail-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px 20px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.detail-grid li {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.detail-grid span {
  color: var(--pine);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.1em;
}

.detail-grid strong {
  font-size: 13px;
  line-height: 1.15;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 10px 18px;
  background: var(--mint);
  border-top: 1px solid var(--line);
}

.card-footer p {
  margin: 0;
  font-size: 12px;
  line-height: 1.25;
}

.card-footer button {
  flex: 0 0 auto;
  padding: 7px 11px;
  color: var(--paper);
  background: var(--pine);
  border: 0;
  border-radius: 7px;
  font: inherit;
  font-size: 12px;
  font-weight: 800;
}

